<section class="panel"><div class="section-heading"><div><span class="eyebrow">02 / RECENT CHECKS</span><h2><?= t('Verification trail') ?></h2></div><span class="hint"><?= t('Latest 20 events') ?></span></div><div class="security-events"><?php foreach($a->db->all('SELECT c.*,o.order_no FROM cy_payment_checks c JOIN cy_orders o ON o.id=c.order_id ORDER BY c.id DESC LIMIT 20') as $check): ?><div class="security-event"><?= icon($check['result']==='paid'?'check':'clock') ?><div class="grow"><a href="<?= e(au('orders',['q'=>$check['order_no']])) ?>"><?= e($check['order_no']) ?></a><time><?= dt((int)$check['created_at'],'Y.m.d H:i') ?></time></div><span class="pill"><?= t($check['result']) ?></span></div><?php endforeach ?></div><p class="hint"><?= t('Only check outcomes are recorded here, never merchant keys or OAuth access tokens.') ?></p></section></div>
